import React from 'react';
import SectionHeading from './SectionHeading';
import Reveal from './Reveal';
import Icon from './icons';
import { now } from '../data/content';

export default function Now() {
  return (
    <section id="now" className="py-20 px-4 sm:px-6">
      <div className="max-w-6xl mx-auto">
        <Reveal>
          <SectionHeading eyebrow={now.eyebrow} heading={now.heading} />
        </Reveal>

        <Reveal delay={80}>
          <div className="mt-8 rounded-2xl border border-indigo-500/20 bg-indigo-500/5 dark:bg-indigo-500/10 p-6 sm:p-8">
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-mono bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
              {now.current.badge}
            </span>
            <h3 className="mt-4 font-display text-2xl font-semibold text-zinc-900 dark:text-zinc-50">
              {now.current.title}
            </h3>
            <p className="mt-3 text-zinc-600 dark:text-zinc-400 leading-relaxed max-w-3xl">
              {now.current.description}
            </p>
            <div className="mt-4 flex flex-wrap gap-2">
              {now.current.tags.map((tag) => (
                <span
                  key={tag}
                  className="px-2.5 py-1 rounded-full text-xs font-mono bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400"
                >
                  {tag}
                </span>
              ))}
            </div>
          </div>
        </Reveal>

        <div className="mt-6 grid sm:grid-cols-3 gap-4">
          {now.threads.map((thread, idx) => (
            <Reveal key={thread.title} delay={120 + idx * 80}>
              <div className="h-full rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-5 transition-transform hover:-translate-y-1 hover:shadow-md">
                <div className="inline-flex items-center justify-center w-9 h-9 rounded-lg bg-indigo-500/10 text-indigo-500 dark:text-indigo-400 mb-3">
                  <Icon name={thread.icon} size={18} />
                </div>
                <h4 className="font-display font-semibold text-zinc-900 dark:text-zinc-50">{thread.title}</h4>
                <p className="mt-1.5 text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed">
                  {thread.description}
                </p>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
